from pathlib import Path
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, PageBreak
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.lib.colors import HexColor
from pypdf import PdfReader

out=Path('output/pdf/nick-stock-news-agent-review.pdf').resolve()
out.parent.mkdir(parents=True,exist_ok=True)
s=getSampleStyleSheet()
s.add(ParagraphStyle(name='TitleX',fontName='Helvetica-Bold',fontSize=25,leading=29,textColor=HexColor('#17384C'),spaceAfter=14))
s.add(ParagraphStyle(name='SectionX',fontName='Helvetica-Bold',fontSize=12,leading=16,textColor=HexColor('#17384C'),spaceBefore=12,spaceAfter=6))
s.add(ParagraphStyle(name='CopyX',fontName='Helvetica',fontSize=9.5,leading=13,spaceAfter=6,textColor=HexColor('#293E4D')))
s.add(ParagraphStyle(name='SmallX',fontName='Helvetica',fontSize=8,leading=11,spaceAfter=5,textColor=HexColor('#526877')))
f=[]
def add(t,style='CopyX'): f.append(Paragraph(t,s[style]))
def section(t): add(t,'SectionX')
add('PREPARED FOR NICOLAS RICHARD (NICK) | REVIEW PROPOSAL','SmallX')
add('Timely stock news.<br/>Simple Telegram delivery.','TitleX')
add('Proposal: 13 September 2026 | Review questions updated: 27 September 2026','SmallX')
add('<b>Recommendation:</b> A small cloud-hosted application that collects permitted news, matches covered companies, removes duplicates and sends Telegram alerts. Target delivery within an hour of original publication. This is a proposed design, not an existing or tested application.')
section('What Nick would receive')
add('Headlines with ticker, publisher, source link and publication time. Labels would identify earnings, financing, acquisitions and regulatory events. Optional AI explanations would follow separately, clearly distinguishing source facts from interpretation.')
add('<b>Coverage:</b> All Nasdaq-listed stocks, Russell Top 200 and S&amp;P 500, with overlaps removed. All relevant announcements remain eligible; potentially market-moving news is flagged rather than used to silently discard other items. Research only, with no portfolio access or trading.')
section('How it would work')
add('<b>Collect news &gt; match companies &gt; check freshness and duplicates &gt; send Telegram alert &gt; add AI explanation.</b>')
add('Proposed checks every ten minutes, subject to source limits. Available streaming feeds can deliver sooner. Late items would be marked delayed; missing publication times would be marked freshness unknown. Neither would count as meeting the one-hour target. The pilot must measure missing announcements as well as delivery speed.')
section('News sources and cost')
add('<b>Alpaca News:</b> First broad-news candidate. Streaming access is documented; current free entitlement and private Telegram-use rights still need confirmation. [1]')
add('<b>SEC and company feeds:</b> Public filing APIs and permitted official RSS feeds would supplement coverage. Filings do not include every company announcement. [2]')
add('<b>Paid fallback:</b> Finlight starts at $29/month. Consider only if pilot results justify it and publisher-content rights are resolved. [3, 4]')
add('<b>Hosting:</b> A $6/month DigitalOcean server is an initial candidate. Capacity must be tested. AI, SMS, backups, taxes and paid data are additional; no all-in price is confirmed. [5]')
add('Start with Telegram, cap AI spending and add SMS later. Yahoo scraping would not be a dependency. Cloud hosting supports operation independently of Nick\'s computer; local operation stops when that computer sleeps or loses connectivity.')
f.append(PageBreak())
add('IMPLEMENTATION AND DEPLOYMENT','SmallX')
add('From pilot to daily use','TitleX')
section('Implementation strategy')
add('<b>Source pilot:</b> Confirm access and permitted use. Compare results against original announcements. Maintain dated company and index membership records from permitted sources, with coverage gaps visible.')
add('<b>Reliable delivery:</b> Build company matching, duplicate handling, persistent queuing and retry handling. Test outages, restarts and Telegram throttling. Include status, pause and resume commands.')
add('<b>AI explanations:</b> Summarize permitted content after headlines. Check accuracy and enforce a spending cap. Headlines continue if AI is unavailable.')
add('<b>Package and trial:</b> Supply a Docker application, configuration template, setup guide, persistent storage, backup instructions and health checks. Measure freshness, coverage gaps, duplicates and relevance during Nick\'s trial.')
section('How Nick would deploy it')
add('These are intended steps after the application is built. We would supply the setup commands and instructions; Nick would not need to write code.')
add('<b>1. Create accounts.</b> Create a Telegram bot through BotFather and start a private chat. Obtain selected news credentials. Nick owns the hosting account and billing. [6]')
add('<b>2. Install the package.</b> Create the cloud server and follow the supplied installation guide. Enter credentials securely in server configuration, not in Telegram messages.')
add('<b>3. Pair and test.</b> Authorize Nick\'s chat only. Run the setup check to confirm source access, send a test alert and verify saved state.')
add('<b>4. Leave it running.</b> Automatic restart would restore service after reboot. Nick uses Telegram. The package would include update, backup, restore and shutdown instructions. An external health check would detect a stopped server.')
section('Reference links')
for label,url in [('1. Alpaca streaming news','https://docs.alpaca.markets/us/docs/streaming-real-time-news'),('2. SEC public APIs','https://www.sec.gov/search-filings/edgar-application-programming-interfaces'),('3. Finlight pricing','https://finlight.me/pricing'),('4. Finlight content-use terms','https://finlight.me/terms-of-use'),('5. DigitalOcean server pricing','https://www.digitalocean.com/pricing/droplets'),('6. Telegram setup and limits','https://core.telegram.org/bots/faq')]:
    add(f'<link href="{url}" color="#126A83">{label}</link>','SmallX')
add('Source and pricing information reflects the original proposal research; it has not been refreshed for this wording update.','SmallX')
f.append(PageBreak())
add('YOUR CHOICES','SmallX')
add('For Nick to review','TitleX')
add('Please choose an option for each question. Our suggestions are starting points; you can choose differently.')
section('1. Should we include S&amp;P 500 companies too?')
add('Nasdaq-listed stocks and Russell Top 200 companies are already in scope. This question concerns additional S&amp;P 500 companies not covered by those lists.')
add('<b>A. Include them (suggested).</b> Benefit: broader company coverage. Tradeoff: more news to review and potentially more data or AI usage. Duplicate companies would not create duplicate alerts.')
add('<b>B. Leave them out.</b> Benefit: a narrower news feed. Tradeoff: you could miss news about S&amp;P 500 companies outside the other lists.')
section('2. Where should the application run?')
add('<b>A. On a rented online server (suggested).</b> Benefit: it can collect news while your computer is off. Tradeoff: a recurring hosting bill and occasional maintenance; outages are still possible.')
add('<b>B. On your computer.</b> Benefit: no separate server subscription. Tradeoff: your computer must stay awake and connected; power or internet interruptions can delay alerts.')
section('3. Would you like AI explanations during the trial?')
add('<b>A. Yes, with a spending limit (suggested).</b> Benefit: a short explanation can help you understand why news may matter. Tradeoff: extra cost and possible interpretation errors. Headlines arrive first; AI explanations follow.')
add('<b>B. Start with headlines and source links only.</b> Benefit: lower cost and fewer messages. Tradeoff: you read and interpret the original news yourself. AI can be added later.')
section('4. How should we handle the one-hour target?')
add('The clock starts when news is originally published, not when our application discovers it. Free sources may publish late or miss some announcements.')
add('<b>A. Test lower-cost sources first (suggested).</b> Benefit: we measure actual results before spending more. Tradeoff: some trial alerts may be late or missing. We report gaps and label known delays rather than promise complete coverage.')
add('<b>B. Require evidence of the target before relying on alerts.</b> Benefit: a stricter go/no-go decision. Tradeoff: a longer evaluation and possibly paid sources; payment alone does not guarantee timing or complete coverage.')
section('5. When news arrives in a burst, how should it appear?')
add('<b>A. Group closely arriving headlines (suggested).</b> Benefit: fewer notifications and less pressure on Telegram limits. Tradeoff: a short grouping delay and less prominence for each headline. Each item retains its ticker, time and link.')
add('<b>B. Send each headline separately.</b> Benefit: each story stands out. Tradeoff: more notifications; Telegram limits can force a queue and delay later messages. [6]')
add('<b>Easy reply:</b> Send your choices as 1A, 2A, 3A, 4A, 5A, or add any preferences in your own words. Choosing AI does not authorize unlimited spending; we would agree the cap before enabling it.','SmallX')
def footer(c,d):
    c.setStrokeColor(HexColor('#D4DEE5')); c.line(54,43,558,43)
    c.setFont('Helvetica',8); c.setFillColor(HexColor('#617383'))
    c.drawString(54,29,'NICK / STOCK NEWS AGENT / PROPOSED DESIGN')
    c.drawRightString(558,29,str(d.page))
SimpleDocTemplate(str(out),pagesize=(612,792),leftMargin=54,rightMargin=54,topMargin=40,bottomMargin=57).build(f,onFirstPage=footer,onLaterPages=footer)
r=PdfReader(out)
print(out)
print('Pages:',len(r.pages))
for i,p in enumerate(r.pages): print('Page',i+1,'characters:',len(p.extract_text()))


